import { Tooltip, Button } from 'animal-island-ui';

const App = () => {
    return (
        <div>
            {/* 基础用法 */}
            <Tooltip title="提示文字">
                <Button>Hover 我</Button>
            </Tooltip>

            {/* 动物主题 island 风格 — bordered 默认 true，箭头更清晰 */}
            <Tooltip variant="island" bordered title="有边框有机气泡">
                <Button>Island</Button>
            </Tooltip>
            <Tooltip variant="island" bordered={false} title="无边框 · 圆点指示">
                <Button>Island 无边框</Button>
            </Tooltip>

            {/* 12 个方向 */}
            <Tooltip title="我在上方" placement="top">
                <Button>Top</Button>
            </Tooltip>
            <Tooltip title="我在左下方" placement="bottom-start">
                <Button>Bottom-Start</Button>
            </Tooltip>

            {/* Click 触发 */}
            <Tooltip title="点击触发" trigger="click">
                <Button>Click</Button>
            </Tooltip>

            {/* Focus 触发 */}
            <Tooltip title="聚焦显示" trigger="focus">
                <input placeholder="点击聚焦" />
            </Tooltip>

            {/* 多行内容 */}
            <Tooltip
                title={
                    <>
                        第一行
                        <br />
                        第二行
                        <br />
                        第三行
                    </>
                }
            >
                <Button>多行</Button>
            </Tooltip>
        </div>
    );
};

export default App;`}),e.jsx(J,{rows:gf})]}),wf=[{prop:"children",desc:"标题内容",type:"ReactNode",defaultVal:"-",required:!0},{prop:"size",desc:"尺寸",type:"'small' | 'middle' | 'large'",defaultVal:"'middle'"},{prop:"color",desc:"配色",type:"'default' | 'app-pink' | 'purple' | 'app-blue' | 'app-yellow' | 'app-orange' | 'app-teal' | 'app-green' | 'app-red' | 'lime-green' | 'yellow-green' | 'brown' | 'warm-peach-pink'",defaultVal:"'default'"},{prop:"variant",desc:"标题样式",type:"'layer' | 'ribbon' | 'tab'",defaultVal:"'layer'"},{prop:"className",desc:"自定义类名",type:"string",defaultVal:"-"},{prop:"style",desc:"自定义样式",type:"React.CSSProperties",defaultVal:"-"}],ua=(t,a,l,s)=>({...ee,padding:40,background:`
